package org.racedaydreams.domain.coaching;
import java.time.*;
import java.util.*;
import org.racedaydreams.domain.*;
import org.racedaydreams.domain.activity.*;
import org.racedaydreams.domain.body.*;
import org.racedaydreams.domain.strength.*;
import static org.racedaydreams.domain.coaching.CoachingTestSuite.*;

public final class WeeklyCoachingTestSuite {
    static int assertions;
    static void verify(boolean ok,String reason){assertions++;if(!ok)throw new AssertionError(reason);}
    public static void main(String[] args){dates();reviews();samples();providers();mass();extra();System.out.println("WeeklyCoachingTestSuite: "+assertions+" checks passed (weekly/return/performance/durability/providers/mass).");}
    static void dates(){
        var p=profile(RaceDistance.TEN_K,3,12,TrainingStrategy.BALANCED);var t=p.preferences();
        var prefs=new TrainingPreferences(t.strategy(),EnumSet.of(DayOfWeek.TUESDAY,DayOfWeek.THURSDAY,DayOfWeek.SATURDAY),3,DayOfWeek.SATURDAY,Set.of(),t.scheduleType(),t.units());
        for(int days:new int[]{1,42,154,365,1095}){var goal=new RaceGoal(RaceDistance.TEN_K,"",START.plusDays(days).with(java.time.temporal.TemporalAdjusters.nextOrSame(DayOfWeek.SUNDAY)),GoalMode.FINISH,null);var runner=new UserProfile(goal,prefs,false);var plan=new OriginalTrainingPlanGenerator().generate(runner,baseline(25,10),START);verify(plan.workouts().stream().anyMatch(w->w.category()==WorkoutCategory.RACE&&w.date().equals(goal.raceDate())),"Sunday race overrides recurring days");verify(plan.workouts().stream().filter(w->w.category()!=WorkoutCategory.RACE).allMatch(w->prefs.runningDays().contains(w.date().getDayOfWeek())),"Training honours days");verify(plan.workouts().stream().noneMatch(w->AdaptiveCoachingEngine.isQuality(w.category())&&w.date().isBefore(goal.raceDate().minusDays(140))),"No distant race-specific intensity");if(days>196){verify(plan.workouts().stream().filter(w->w.date().isBefore(goal.raceDate().minusDays(196))&&w.category()==WorkoutCategory.LONG_RUN).allMatch(w->w.distanceKm()<=13.1),"Distant long runs do not drift to peak mileage");Map<LocalDate,Double> volume=new HashMap<>();for(var w:plan.workouts())if(w.date().isBefore(goal.raceDate().minusDays(196))&&w.distanceKm()!=null)volume.merge(w.date().with(java.time.temporal.TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY)),w.distanceKm(),Double::sum);verify(volume.values().stream().allMatch(x->x<=31.5),"Foundation volume is bounded near baseline before the build");}}
        var response=new RunExecution("a","run","v",null,null,"");for(var type:List.of(WorkoutCategory.RACE,WorkoutCategory.TIME_TRIAL))verify(RunScoreEngine.analyse(planned(type),actual("a",8,10.0,"run"),response).score()==10,"Deliberate race RPE 10 does not penalise objective");
    }
    static PlanVersion version(){var p=profile(RaceDistance.HALF_MARATHON,4,12,TrainingStrategy.BALANCED);var ws=new ArrayList<PlannedWorkout>();for(int week=-4;week<5;week++)for(int d:new int[]{1,3,6}){var date=START.plusWeeks(week).plusDays(d);ws.add(new PlannedWorkout("w"+date,date,d==6?WorkoutCategory.LONG_RUN:WorkoutCategory.EASY_RUN,8.0,null,List.of(),"Original"));}return new PlanVersion("v","p",1,NOW,"Original",p,"Evidence",new TrainingPlan("p",START.minusWeeks(4),START.plusWeeks(5),List.of(),ws));}
    static List<ActivityRecord> history(PlanVersion v,boolean strain,boolean missThursday){var out=new ArrayList<ActivityRecord>();for(var w:v.plan().workouts())if(w.date().isBefore(START)&&!(missThursday&&w.date().getDayOfWeek()==DayOfWeek.THURSDAY)){var end=w.date().atTime(12,0).toInstant(ZoneOffset.UTC);boolean recent=w.date().isAfter(START.minusWeeks(2));out.add(new ActivityRecord("a"+w.id(),new SourceIdentity("manual",w.id(),null),end.minusSeconds(3000),end,ZoneOffset.UTC,ZoneOffset.UTC,strain&&recent?5000.0:8000.0,null,null,null,null,null,strain&&recent?9.0:3.0,"",List.of(),List.of(),w.id(),null));}return out;}
    static void reviews(){var v=version();var good=history(v,false,false);var r=WeeklyCoaching.review(v,List.of(v),good,List.of(),List.of(),List.of(),START,null);verify(r.completed()==3&&r.planned()==3,"Complete week");verify(r.choices().size()==1,"Perfect weeks: no manufactured adaptation");verify(r.recommendation().contains("No adjustment"),"No change is explicit");var bad=WeeklyCoaching.review(v,List.of(v),history(v,true,false),List.of(),List.of(),List.of(),START,null);verify(bad.choices().stream().anyMatch(c->c.id().equals("hold")),"Repeated shortening and RPE suggest bounded hold");var hold=bad.choices().stream().filter(c->c.id().equals("hold")).findFirst().orElseThrow();verify(hold.replacements().stream().allMatch(w->!w.date().isBefore(START)&&w.date().isBefore(START.plusWeeks(2))),"Only next two weeks");var kept=WeeklyCoaching.apply(v,bad,bad.choices().get(0),Set.of());verify(kept.equals(v.plan()),"Rejected adaptation unchanged");var changed=WeeklyCoaching.apply(v,bad,hold,Set.of());verify(changed.workouts().stream().filter(w->w.date().isBefore(START)).toList().equals(v.plan().workouts().stream().filter(w->w.date().isBefore(START)).toList()),"History preserved");var missed=WeeklyCoaching.review(v,List.of(v),history(v,false,true),List.of(),List.of(),List.of(),START,null);verify(missed.observations().stream().anyMatch(s->s.contains("THURSDAY")&&s.contains("4")),"Recurring Thursday misses");verify(missed.choices().size()==1,"Misses alone never create catch-up volume");
        for(int gap:new int[]{7,14,28,60})for(String reason:List.of("Illness","Travel / life","Injury concern")){var bridge=WeeklyCoaching.review(v,List.of(v),good,List.of(),List.of(),List.of(),START,new WeeklyCoaching.Interruption(START.minusDays(gap),START,reason));var choice=bridge.choices().stream().filter(c->c.id().equals("return")).findFirst();verify(choice.isPresent()==(gap>=14),"Bridge only after meaningful break");if(choice.isPresent())verify(choice.get().replacements().stream().allMatch(w->w.distanceKm()<=8&&w.category()==WorkoutCategory.EASY_RUN),"Return never adds missed mileage or hard effort");}
        var results=List.of(new RecordedResult("old",PerformanceDistance.FIVE_K,Duration.ofMinutes(30),START.minusMonths(2),"Race",ResultSource.OFFICIAL_CHIP,null,""),new RecordedResult("new",PerformanceDistance.FIVE_K,Duration.ofMinutes(27),START.minusDays(3),"Race",ResultSource.OFFICIAL_CHIP,null,""));var improving=WeeklyCoaching.review(v,List.of(v),good,List.of(),List.of(),results,START,null);verify(improving.channels().stream().anyMatch(c->c.name().equals("Performance trend")&&c.state()==WeeklyCoaching.State.IMPROVING),"Major PB needs controlled consistent history");verify(WeeklyCoaching.review(v,List.of(v),List.of(),List.of(),List.of(),results,START,null).channels().stream().noneMatch(c->c.state()==WeeklyCoaching.State.IMPROVING),"One isolated result insufficient");verify(v.goalSnapshot().equals(version().goalSnapshot()),"Review never changes race target");
    }
    static ActivityRecord sampled(String id,String provider,String origin,double fade,boolean gap,boolean hr){var samples=new ArrayList<DistanceSample>();double metres=0;for(int i=0;i<=360;i++){if(i>0)metres+=i<=180?30:30/(1+fade);samples.add(new DistanceSample(Duration.ofSeconds(i*10),metres,hr?150.0:null,null,null,gap&&i==200));}return new ActivityRecord(id,new SourceIdentity(provider,id,origin),NOW.minusSeconds(3600),NOW,ZoneOffset.UTC,ZoneOffset.UTC,metres,null,null,null,null,null,3.0,"",samples,List.of(),null,null);}
    static void samples(){for(double fade:new double[]{-.1,0,.2})for(boolean hr:new boolean[]{false,true}){var d=LongRunDurability.analyse(sampled("s","manual",null,fade,false,hr));verify(d.sufficient(),"Qualified samples");verify(Math.abs(d.paceFadePercent()-fade*100)<.2,"Real time-half pace fade");verify((d.heartRateDriftPercent()!=null)==hr,"HR optional");verify(d.cadenceChangePercent()==null,"Missing cadence remains missing");}verify(!LongRunDurability.analyse(actual("empty",8,3.0,null)).sufficient(),"No aggregate fake durability");verify(!LongRunDurability.analyse(sampled("gap","manual",null,.2,true,false)).sufficient(),"Discontinuities reject");}
    static void providers(){verify(ActivitySources.normalizeLegacyPreference("SAMSUNG_EXPERIMENTAL").equals("HEALTH_CONNECT"),"Legacy preference normalizes");verify(ActivitySources.normalizeLegacyPreference("AUTOMATIC").equals("HEALTH_CONNECT"),"Automatic normalizes");}

    static void mass(){verify(Math.abs(MassUnit.LB.toKilograms(100)-45.359237)<1e-8,"lb exact canonical");for(double kg:new double[]{0,40,80,200})verify(Math.abs(MassUnit.LB.toKilograms(MassUnit.LB.fromKilograms(kg))-kg)<1e-9,"Round trip");var historical=new HistoricalStrengthRecord("h",StrengthExercise.starters().get(0),100,5,null,HistoricalStrengthRecord.DatePrecision.UNKNOWN,"");verify(historical.date()==null,"Unknown historical date not invented");}
    static void extra(){
        var v=version();var completedLate=history(v,false,false);var lateId="aw"+START.minusDays(1);var lateRun=completedLate.stream().filter(a->a.id().equals(lateId)).findFirst().orElseThrow();completedLate.remove(lateRun);completedLate.add(new ActivityRecord(lateRun.id(),lateRun.source(),NOW.minusSeconds(3600),NOW,ZoneOffset.UTC,ZoneOffset.UTC,8000.0,null,null,null,null,null,3.0,"Completed after the reviewed week",List.of(),List.of(),lateRun.plannedWorkoutId(),null));verify(WeeklyCoaching.review(v,List.of(v),completedLate,List.of(),List.of(),List.of(),START,null).completed()==2,"Late completion is not fabricated as completed inside the reviewed week");
        var longRun=new PlannedWorkout("long",START.plusDays(1),WorkoutCategory.LONG_RUN,12.0,null,List.of(),"Endurance");var plan=new TrainingPlan("p",START,START.plusWeeks(4),List.of(),List.of(longRun));var upcoming=new PlanVersion("v","p",1,NOW,"Test",v.goalSnapshot(),"Evidence",plan);
        var proposal=AdaptiveCoachingEngine.review(upcoming,List.of(),List.of(),List.of(strengthSession("legs",80,5,START)),START,NOW);
        verify(proposal.isPresent()&&proposal.get().workoutId().equals("long"),"Recorded heavy legs can affect long runs, not only quality");
        var previous=v.plan().workouts().stream().filter(w->w.date().isBefore(START)).filter(w->w.date().getDayOfWeek()==DayOfWeek.THURSDAY).findFirst().orElseThrow();
        var moved=new PlannedWorkout(previous.id(),previous.date().plusDays(1),previous.category(),previous.distanceKm(),previous.duration(),previous.segments(),"Moved");var list=new ArrayList<>(v.plan().workouts());list.set(list.indexOf(previous),moved);var mv=new PlanVersion("moved","p",2,NOW.plusSeconds(1),"Moved",v.goalSnapshot(),"Evidence",new TrainingPlan("p",v.plan().startDate(),v.plan().endDate(),v.plan().phases(),list));
        var r=WeeklyCoaching.review(mv,List.of(v,mv),history(mv,false,false),List.of(),List.of(),List.of(),START,null);verify(r.completed()==3,"Moved completed sessions not counted as missed in their completion week");
        var bad=sampled("bad","manual",null,0,false,false);var samples=new ArrayList<>(bad.samples());samples.set(10,new DistanceSample(Duration.ofSeconds(100),100000,null,null,null,false));var corrupt=new ActivityRecord(bad.id(),bad.source(),bad.start(),bad.end(),bad.startOffset(),bad.endOffset(),bad.distanceMetres(),null,null,null,null,null,null,"",samples,List.of(),null,null);verify(!LongRunDurability.analyse(corrupt).sufficient(),"GPS jumps cannot become durability evidence");
        var quality=new PlannedWorkout("quality",START.plusDays(3),WorkoutCategory.TEMPO_THRESHOLD_RUN,8.0,null,List.of(new WorkoutSegment(WorkoutSegment.Kind.RUN,8.0,null,300.0,320.0,null,6.0,"Controlled")),"Quality");var withQuality=new ArrayList<>(v.plan().workouts());withQuality.add(quality);var pv=new PlanVersion("q","p",1,NOW,"Test",v.goalSnapshot(),"Evidence",new TrainingPlan("p",v.plan().startDate(),v.plan().endDate(),List.of(),withQuality));var results=List.of(new RecordedResult("o",PerformanceDistance.FIVE_K,Duration.ofMinutes(30),START.minusMonths(2),"",ResultSource.OFFICIAL_CHIP,null,""),new RecordedResult("n",PerformanceDistance.FIVE_K,Duration.ofMinutes(27),START.minusDays(3),"",ResultSource.MANUAL,null,""));var pr=WeeklyCoaching.review(pv,List.of(pv),history(v,false,false),List.of(),List.of(),results,START,null);var pace=pr.choices().stream().filter(c->c.id().equals("paces")).findFirst().orElseThrow();verify(pace.replacements().size()==1,"PB review changes only numerical quality ranges");verify(Math.abs(pace.replacements().get(0).segments().get(0).minimumSecondsPerKm()-291)<.001,"Modest proposed range is inspectable");var changed=WeeklyCoaching.apply(pv,pr,pace,Set.of());verify(changed.workouts().stream().filter(w->w.category()==WorkoutCategory.EASY_RUN).toList().equals(pv.plan().workouts().stream().filter(w->w.category()==WorkoutCategory.EASY_RUN).toList()),"Easy pace and prescriptions not forced faster");verify(pv.goalSnapshot().raceGoal().targetTime().equals(v.goalSnapshot().raceGoal().targetTime()),"Race target unchanged by pace proposal");
    }
}
